import{analyze}from"./analyze.js";import{buildReportFromAnalysis}from"./report.js";export async function clientAnalyze(e={}){return analyze(e)}export async function clientReport(e={}){return buildReportFromAnalysis(e,analyze)}export function clientMeta(){return{rtt:1,module:"API.Route.Client",version:"1.0.0-alpha",environment:"browser",endpoints:["analyze","report","meta"]}}export async function routeClient(e,r={}){switch(e){case"analyze":return clientAnalyze(r);case"report":return clientReport(r);case"meta":return clientMeta();default:return{error:`Unknown client route: ${e}`}}}

